const safeFilename = (value: string) => value.trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase() || 'interactiq-report';
const downloadBlob = (blob: Blob, filename: string) => { const href=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=href; link.download=filename; link.click(); window.setTimeout(()=>URL.revokeObjectURL(href),1000); };
const csvCell = (value: string) => {
  // Excel treats values such as 10/19 as dates and leading formula characters
  // as executable formulas. A leading tab preserves the visible text safely.
  const text = String(value);
  const safe = /^(?:[=+\-@]|\d+(?:\.\d+)?\/\d+(?:\.\d+)?)$/.test(text.trim()) ? `\t${text}` : text;
  return `"${safe.replaceAll('"','""')}"`;
};
const exportCsvRows = (filename: string, rows: ExportRow[]) => { const csv='\uFEFF'+rows.map((row)=>row.map(csvCell).join(',')).join('\r\n'); downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`${safeFilename(filename)}.csv`); };
const wrapCanvasText = (context:CanvasRenderingContext2D,value:string,maxWidth:number) => {
  const words=String(value).replace(/\s+/g,' ').trim().split(' ').filter(Boolean); const lines:string[]=[]; let line='';
  const pushLongWord=(word:string)=>{let part='';for(const character of word){if(part&&context.measureText(part+character).width>maxWidth){lines.push(part);part=character;}else part+=character;}if(part)line=part;};
  for(const word of words){const candidate=line?`${line} ${word}`:word;if(context.measureText(candidate).width<=maxWidth)line=candidate;else{if(line){lines.push(line);line='';}if(context.measureText(word).width>maxWidth)pushLongWord(word);else line=word;}}
  if(line||!lines.length)lines.push(line); return lines;
};
const reportCanvas = (title:string,subtitle:string,headers:string[],rows:ExportRow[],minimumHeight=0) => {
  const width=2400,padding=72,headerHeight=250; const weights=headers.map((header)=>/^(rank|no\.?|percent|score|maximum)$/i.test(header) ? 0.75 : /email|quiz|submitted/i.test(header) ? 1.6 : 1.25); const totalWeight=weights.reduce((sum,value)=>sum+value,0); const columnWidths=weights.map((value)=>((width-padding*2)*value)/totalWeight);
  const measure=document.createElement('canvas').getContext('2d'); if(!measure)throw new Error('Canvas is unavailable.'); measure.font='24px Arial';
  const rowHeights=rows.map((row)=>Math.max(54,...row.map((cell,index)=>wrapCanvasText(measure,String(cell),columnWidths[index]!-26).length*30+18))); const height=Math.max(minimumHeight,headerHeight+rowHeights.reduce((sum,value)=>sum+value,0)+80); const canvas=document.createElement('canvas');canvas.width=Math.max(width,Math.ceil(height*1.42));canvas.height=height;const context=canvas.getContext('2d');if(!context)throw new Error('Canvas is unavailable.');
  context.fillStyle='#f8f6f2';context.fillRect(0,0,canvas.width,height);context.fillStyle='#17151c';context.font='700 52px Arial';context.fillText(title,padding,76);context.fillStyle='#655f69';context.font='26px Arial';context.fillText(subtitle,padding,120);context.fillStyle='#6657ff';context.fillRect(padding,150,width-padding*2,7);
  let x=padding;context.fillStyle='#1e1b26';context.font='700 23px Arial';headers.forEach((header,index)=>{context.fillText(header,x+10,212);x+=columnWidths[index]!;});context.font='24px Arial';let y=headerHeight;
  rows.forEach((row,rowIndex)=>{const rowHeight=rowHeights[rowIndex]!;if(rowIndex%2===0){context.fillStyle='#ffffff';context.fillRect(padding-8,y,width-padding*2+16,rowHeight);}x=padding;context.fillStyle='#26222d';row.forEach((cell,columnIndex)=>{wrapCanvasText(context,String(cell),columnWidths[columnIndex]!-26).forEach((line,lineIndex)=>context.fillText(line,x+10,y+34+lineIndex*30));x+=columnWidths[columnIndex]!;});y+=rowHeight;}); return canvas;
};
const exportPngRows = (filename:string,title:string,subtitle:string,headers:string[],rows:ExportRow[]) => { const canvas=reportCanvas(title,subtitle,headers,rows); canvas.toBlob((blob)=>blob&&downloadBlob(blob,`${safeFilename(filename)}.png`),'image/png'); };
const bytesFromText=(value:string)=>new TextEncoder().encode(value);
const concatBytes=(chunks:Uint8Array[])=>{const size=chunks.reduce((sum,chunk)=>sum+chunk.length,0);const result=new Uint8Array(size);let offset=0;for(const chunk of chunks){result.set(chunk,offset);offset+=chunk.length;}return result;};
const exportPdfCanvases = (filename:string,pages:HTMLCanvasElement[]) => {
  const objects:Array<Uint8Array|null>=[null,null]; const pageIds:number[]=[];
  pages.forEach((canvas,index)=>{const pageId=objects.length+1,imageId=pageId+1,contentId=pageId+2;pageIds.push(pageId); const jpeg=atob(canvas.toDataURL('image/jpeg',0.76).split(',')[1]!);const image=new Uint8Array(jpeg.length);for(let i=0;i<jpeg.length;i++)image[i]=jpeg.charCodeAt(i); const content=`q 842 0 0 595 0 0 cm /Im${index} Do Q`; objects.push(bytesFromText(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im${index} ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`)); objects.push(concatBytes([bytesFromText(`<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`),image,bytesFromText('\nendstream')])); objects.push(bytesFromText(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`)); });
  objects[0]=bytesFromText('<< /Type /Catalog /Pages 2 0 R >>'); objects[1]=bytesFromText(`<< /Type /Pages /Kids [${pageIds.map((id)=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`);
  const chunks=[bytesFromText('%PDF-1.4\n')];const offsets=[0];let offset=chunks[0]!.length;objects.forEach((body,index)=>{offsets[index+1]=offset;const chunk=concatBytes([bytesFromText(`${index+1} 0 obj\n`),body!,bytesFromText('\nendobj\n')]);chunks.push(chunk);offset+=chunk.length;});const xref=offset;chunks.push(bytesFromText(`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map((value)=>`${String(value).padStart(10,'0')} 00000 n `).join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`)); downloadBlob(new Blob([concatBytes(chunks)],{type:'application/pdf'}),`${safeFilename(filename)}.pdf`);
};
const exportPortraitPdfCanvases = (filename:string,pages:HTMLCanvasElement[]) => {
  const objects:Array<Uint8Array|null>=[null,null];const pageIds:number[]=[];
  pages.forEach((canvas,index)=>{const pageId=objects.length+1,imageId=pageId+1,contentId=pageId+2;pageIds.push(pageId);const jpeg=atob(canvas.toDataURL('image/jpeg',0.82).split(',')[1]!);const image=new Uint8Array(jpeg.length);for(let i=0;i<jpeg.length;i++)image[i]=jpeg.charCodeAt(i);const content=`q 595 0 0 842 0 0 cm /Im${index} Do Q`;objects.push(bytesFromText(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im${index} ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`));objects.push(concatBytes([bytesFromText(`<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`),image,bytesFromText('\nendstream')]));objects.push(bytesFromText(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`));});
  objects[0]=bytesFromText('<< /Type /Catalog /Pages 2 0 R >>');objects[1]=bytesFromText(`<< /Type /Pages /Kids [${pageIds.map((id)=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`);const chunks=[bytesFromText('%PDF-1.4\n')];const offsets=[0];let offset=chunks[0]!.length;objects.forEach((body,index)=>{offsets[index+1]=offset;const chunk=concatBytes([bytesFromText(`${index+1} 0 obj\n`),body!,bytesFromText('\nendobj\n')]);chunks.push(chunk);offset+=chunk.length;});const xref=offset;chunks.push(bytesFromText(`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map((value)=>`${String(value).padStart(10,'0')} 00000 n `).join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`));downloadBlob(new Blob([concatBytes(chunks)],{type:'application/pdf'}),`${safeFilename(filename)}.pdf`);
};
const reviewPdfCanvases=(review:AttemptReview,score:number)=>{
  const width=1240,height=1754,margin=82,bottom=110,contentWidth=width-margin*2;const pages:HTMLCanvasElement[]=[];let context!:CanvasRenderingContext2D;let y=margin;
  const startPage=()=>{const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;context=canvas.getContext('2d')!;context.fillStyle='#fff';context.fillRect(0,0,width,height);pages.push(canvas);y=margin;if(pages.length>1){context.fillStyle='#6657ff';context.font='700 24px Arial';context.fillText(`InteractIQ submission review · ${review.studentFullName||'Student'} · continued`,margin,y);y+=46;}};
  const ensure=(space:number)=>{if(y+space>height-bottom)startPage();};
  const lines=(value:unknown,font:string,color:string,lineHeight=34,indent=0)=>{context.font=font;context.fillStyle=color;for(const line of wrapCanvasText(context,String(value??'—')||'—',contentWidth-indent)){ensure(lineHeight+8);context.fillText(line,margin+indent,y);y+=lineHeight;}};
  startPage();context.fillStyle='#6657ff';context.fillRect(margin,y,contentWidth,7);y+=50;lines('InteractIQ submission review','700 46px Arial','#17151c',54);lines(review.studentFullName||'Student','700 30px Arial','#2d2830',40);lines(`${review.studentClassName||'No class'} · ${review.studentEmail||''}`,'24px Arial','#665f69',34);lines(`Submitted ${review.submittedAt?malaysiaDate(review.submittedAt):'—'} · Provisional score ${score}/${review.maxScore}`,'24px Arial','#665f69',34);y+=24;
  review.answers.forEach((answer,index)=>{ensure(230);context.strokeStyle='#dcd6cf';context.lineWidth=2;context.beginPath();context.moveTo(margin,y);context.lineTo(width-margin,y);context.stroke();y+=36;lines(`QUESTION ${index+1} · ${answer.questionType.replaceAll('_',' ')}`,'700 25px Arial','#5145c4',34);lines(textOf(answer.prompt)||'Question','700 27px Arial','#17151c',38);y+=10;lines('STUDENT ANSWER','700 19px Arial','#67605a',28);lines(answerText(answer.answer),'24px Arial','#2a2522',34,18);y+=8;lines('CORRECT ANSWER','700 19px Arial','#176b43',28);lines(answerText(answer.correctAnswer),'24px Arial','#176b43',34,18);y+=8;lines(answer.aiMarkingStatus==='PENDING'&&answer.teacherPoints===null?'MARK: Waiting for AI marking':`MARK: ${answer.teacherPoints??answer.aiSuggestedPoints??answer.awardedPoints}/${answer.maxPoints}`,'700 22px Arial','#17151c',32);if(answer.teacherFeedback||answer.aiFeedback){lines('FEEDBACK','700 19px Arial','#67605a',28);lines(answer.teacherFeedback||answer.aiFeedback,'22px Arial','#4f4944',32,18);}y+=26;});
  pages.forEach((canvas,index)=>{const pageContext=canvas.getContext('2d')!;pageContext.fillStyle='#6d665f';pageContext.font='20px Arial';pageContext.fillText(`InteractIQ · Page ${index+1} of ${pages.length}`,margin,height-52);pageContext.textAlign='right';pageContext.fillText(`${review.studentFullName||'Student'} · ${score}/${review.maxScore}`,width-margin,height-52);pageContext.textAlign='left';});return pages;
};
const exportPdfRows = (filename:string,title:string,subtitle:string,headers:string[],rows:ExportRow[],pageSize=22) => { exportPdfCanvases(filename,Array.from({length:Math.max(1,Math.ceil(rows.length/pageSize))},(_,index)=>reportCanvas(title,`${subtitle} · Page ${index+1}`,headers,rows.slice(index*pageSize,(index+1)*pageSize),1690))); };
const exportRosterRows = (format:'png'|'pdf',title:string,subtitle:string,headers:string[],rows:ExportRow[]) => {
  const pages:HTMLCanvasElement[]=[];
  // Repeat student identity on each horizontal page, with at most two attempts.
  for(let col=3;col<headers.length-1;col+=4){
    const columns=[0,1,2,...Array.from({length:Math.min(4,headers.length-1-col)},(_,i)=>col+i),headers.length-1];
    for(let row=0;row<Math.max(1,rows.length);row+=22){
      pages.push(reportCanvas(title,`${subtitle} · Page ${pages.length+1}`,columns.map(i=>headers[i]!),rows.slice(row,row+22).map(values=>columns.map(i=>values[i]??'')),1690));
    }
  }
  if(format==='pdf')exportPdfCanvases(title,pages);
  else pages.forEach((canvas,index)=>canvas.toBlob(blob=>blob&&downloadBlob(blob,`${safeFilename(title)}-${index+1}.png`),'image/png'));
};
