const message = <T,>(payload: ApiResponse<T>, fallback: string) => payload.success ? fallback : payload.error.message;
const textOf = (doc: RichTextDocument) => {
  const walk = (nodes: RichTextDocument['content']): string => nodes.map((node) => `${node.text ?? ''}${node.content ? walk(node.content) : ''}`).join(' ');
  return walk(doc.content).replace(/\s+/g, ' ').trim();
};
const duration = (seconds: number) => seconds < 60 ? `${seconds}s` : `${seconds / 60} min`;
const malaysiaDate = (value: string | Date) => {
  const date = value instanceof Date ? value : new Date(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(value) ? `${value.replace(' ', 'T')}Z` : value);
  return Number.isNaN(date.valueOf()) ? '—' : date.toLocaleString('ms-MY', { timeZone: 'Asia/Kuala_Lumpur' });
};
const escapeHtml = (value: unknown) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[character]!);
const answerText = (value: string | string[] | null | undefined) => Array.isArray(value) ? value.join(', ') : value || '—';
const answered = (value: string | string[] | undefined) => Array.isArray(value) ? value.length > 0 : Boolean(value?.trim());
const safeUrl = (value: unknown) => typeof value === 'string' && (/^https?:\/\//i.test(value) || value.startsWith('/') || value.startsWith('#')) ? value : '';
const publicAsset = (path: string) => `${import.meta.env.BASE_URL}${path.replace(/^\//, '')}`;

