function HeroArtwork({ variant }: { variant: 'login' | 'home' }) {
  const [playing, setPlaying] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(() => typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches);
  useEffect(() => {
    const preference = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReducedMotion(preference.matches);
    preference.addEventListener('change', update);
    return () => preference.removeEventListener('change', update);
  }, []);
  return <div className={`hero-artwork hero-artwork--${variant}${playing && !reducedMotion ? ' hero-artwork--playing' : ''}`} aria-hidden="true">
    <img className="hero-artwork__poster" src={publicAsset(`assets/${variant === 'login' ? 'login-hero' : 'home-hero'}.webp`)} alt="" decoding="async" />
    {!reducedMotion && <video
      className="hero-artwork__video"
      src={publicAsset(variant === 'home' ? 'assets/home-motion.mp4' : 'assets/login-motion.mp4')}
      autoPlay
      muted
      loop
      playsInline
      preload="metadata"
      disablePictureInPicture
      onPlaying={() => setPlaying(true)}
      onError={() => setPlaying(false)}
    />}
  </div>;
}

