function RichDocument({ document }: { document: RichTextDocument }) {
  const render = (nodes: RichTextDocument['content'] = []): ReactNode => nodes.map((node, index) => {
    const children = node.text ?? (node.content ? render(node.content) : null);
    let marked: ReactNode = children;
    for (const mark of node.marks ?? []) {
      if (mark.type === 'bold') marked = <strong>{marked}</strong>;
      if (mark.type === 'italic') marked = <em>{marked}</em>;
      if (mark.type === 'underline') marked = <u>{marked}</u>;
      if (mark.type === 'strike') marked = <s>{marked}</s>;
      if (mark.type === 'superscript') marked = <sup>{marked}</sup>;
      if (mark.type === 'subscript') marked = <sub>{marked}</sub>;
      if (mark.type === 'highlight') marked = <mark>{marked}</mark>;
      if (mark.type === 'textStyle' && (mark.attrs?.color || mark.attrs?.fontSize)) marked = <span style={{ color: mark.attrs.color, fontSize: mark.attrs.fontSize ? `${mark.attrs.fontSize}px` : undefined }}>{marked}</span>;
      if (mark.type === 'link' && safeUrl(mark.attrs?.href)) marked = <a href={String(mark.attrs?.href)} rel="noreferrer" target="_blank">{marked}</a>;
    }
    const key = `${node.type}-${index}`;
    if (node.type === 'image') { const src = safeUrl(node.attrs?.src); return src ? <figure className="prompt-image" key={key}><img alt={String(node.attrs?.alt ?? 'Question image')} src={src} /></figure> : null; }
    if (node.type === 'heading') { const level = Number(node.attrs?.level); return level === 3 ? <h3 key={key}>{marked}</h3> : <h2 key={key}>{marked}</h2>; }
    if (node.type === 'bulletList') return <ul key={key}>{marked}</ul>;
    if (node.type === 'orderedList') return <ol key={key}>{marked}</ol>;
    if (node.type === 'listItem') return <li key={key}>{marked}</li>;
    if (node.type === 'blockquote') return <blockquote key={key}>{marked}</blockquote>;
    if (node.type === 'hardBreak') return <br key={key} />;
    if (node.type === 'paragraph') return <p key={key}>{marked}</p>;
    return <Fragment key={key}>{marked}</Fragment>;
  });
  return <div className="rendered-document">{render(document.content)}</div>;
}

class ViewErrorBoundary extends Component<{ children: ReactNode; fallback: ReactNode; resetKey: string }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error: Error, info: ErrorInfo) { console.error('View failed', error, info); }
  componentDidUpdate(previous: Readonly<{ resetKey: string }>) { if (previous.resetKey !== this.props.resetKey && this.state.failed) this.setState({ failed: false }); }
  render() { return this.state.failed ? this.props.fallback : this.props.children; }
}

function BasicEditor({ value, onChange }: { value: RichTextDocument; onChange: (value: RichTextDocument) => void }) {
  const update = (plainText: string): RichTextDocument => ({
    type: 'doc',
    content: plainText.split(/\r?\n/).map((line) => line
      ? { type: 'paragraph', content: [{ type: 'text', text: line }] }
      : { type: 'paragraph' }),
  });
  return <textarea className="editor-fallback__input" onChange={(event) => onChange(update(event.target.value))} rows={8} value={textOf(value)} />;
}

function SafeEditor({ value, onChange, onUploadImage }: { value: RichTextDocument; onChange: (value: RichTextDocument) => void; onUploadImage: (file: File) => Promise<string> }) {
  return <ViewErrorBoundary fallback={<BasicEditor value={value} onChange={onChange} />} resetKey={JSON.stringify(value)}>
    <Suspense fallback={<p className="muted">Loading editor…</p>}><RichTextEditor value={value} onChange={onChange} onUploadImage={onUploadImage} /></Suspense>
  </ViewErrorBoundary>;
}

type IntroAudience = 'ADMIN' | 'STUDENT' | 'SIGNOUT';

function HelloIntro({ audience, onComplete }: { audience: IntroAudience; onComplete: () => void }) {
  useEffect(() => {
    const timer = window.setTimeout(onComplete, window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 600 : 2300);
    return () => window.clearTimeout(timer);
  }, []);
  const signingOut = audience === 'SIGNOUT';
  const word = signingOut ? 'Bye Bye' : 'Hello';
  return <div className={`hello-intro ${signingOut ? 'hello-intro--farewell' : ''}`} role="status" aria-label={signingOut ? 'Signing out of InteractIQ' : 'Opening InteractIQ'}>
    <div className="hello-intro__glow" />
    <div className="hello-intro__word" aria-hidden="true">{word}<span>{word}</span></div>
    <p>{signingOut ? 'See you again' : audience === 'STUDENT' ? 'Your activity is ready' : 'Welcome to InteractIQ'}</p>
  </div>;
}

